pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 blockTimestamp, uint256 blockNumber) public {
        // Ensure timestamp is in the future from the contract's perspective
        vm.warp(blockTimestamp);
        vm.roll(blockNumber);
        // Ensure timestamp > pastBlockTime (which is initially 0)
        vm.assume(blockTimestamp > 0);

        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);

        uint256 balanceBefore = address(c).balance;

        vm.prank(sender);
        (bool ok, ) = address(c).call{value: 10 ether}("");

        // For the reference contract, the call should succeed and balance increases by 10 ether.
        // The buggy contract reverts, so the balance should not increase.
        // The property: if the call succeeds, the balance must have increased by exactly 10 ether.
        // Since the reference contract always succeeds for these inputs, its balance always increases.
        // The buggy contract reverts, so its balance doesn't increase, violating the property when ok is true.
        assertTrue(!ok || address(c).balance == balanceBefore + 10 ether);
    }
}

