pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 blockTimestamp1, uint256 blockTimestamp2, uint8 delayBlocks) public {
        // Ensure timestamps are in a realistic range and strict ordering is possible.
        vm.assume(blockTimestamp1 > 0 && blockTimestamp2 >= blockTimestamp1);
        // Keep delay positive but small enough to be realistic.
        vm.assume(delayBlocks > 0);

        // First call: warp to blockTimestamp1, set block.number to some value, call fallback with 10 ether.
        vm.warp(blockTimestamp1);
        vm.roll(uint256(blockTimestamp1)); // arbitrary, just to avoid condition triggered unintentionally
        address sender = address(0x1234);
        vm.deal(sender, 20 ether);
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        // Record the updated pastBlockTime after first call.
        uint256 recorded1 = c.pastBlockTime();

        // Advance time and blocks.
        uint256 blockTimestamp2Actual = blockTimestamp2;
        vm.warp(blockTimestamp2Actual);
        vm.roll(block.number + delayBlocks);

        // Second call: same sender, same amount.
        vm.prank(sender);
        c.fallback{value: 10 ether}();

        uint256 recorded2 = c.pastBlockTime();

        // The rule: after any successful call, the stored pastBlockTime must be strictly greater than the
        // block timestamp of the previous successful call.
        // Reference satisfies this because it requires block.timestamp > pastBlockTime;
        // mutant removes that check, so recorded2 can be <= blockTimestamp1 or equal to recorded1,
        // breaking the strict monotonic increase over time.
        assertTrue(recorded2 > blockTimestamp1);
    }
}

