pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address sender, uint8 seed0, uint8 seed1) public {
        // Admissible: sender is an EOA, but we need to observe its balance change.
        // Block number must be >0 to potentially be divisible by 15.
        // We set block number to a random value, then add 15 to ensure at least one multiple of 15 is possible.
        // But the fuzzer controls seed0, seed1; we can construct block number.
        // We want the fuzzer to find a block number divisible by 15.
        // Use seed0 to set block number; bound to keep reasonable.
        uint256 blk = uint256(seed0) * 256 + uint256(seed1);
        blk = bound(blk, 1, type(uint64).max);
        vm.roll(blk);
        // Ensure sender has enough ether and no contract code (it's an EOA).
        vm.assume(sender != address(0));
        vm.deal(sender, 20 ether);
        // Ensure pastBlockTime condition passes: warp to some future time.
        vm.warp(block.timestamp + 1 days);
        // Record sender balance before call.
        uint256 balBefore = sender.balance;
        // Execute fallback with 10 ether.
        vm.prank(sender);
        c.fallback{value: 10 ether}();
        // Record sender balance after call.
        uint256 balAfter = sender.balance;
        // General rule: if block.number is divisible by 15, sender balance must increase by exactly 10 ether.
        // If not divisible, sender balance must decrease by exactly 10 ether (no transfer).
        // The buggy version never transfers, so sender balance always decreases by 10 ether.
        // Therefore, the property should hold for the reference and fail for the buggy version when block.number % 15 == 0.
        // We assert: if blk % 15 == 0 => balAfter > balBefore, else balAfter < balBefore.
        // But the reference always satisfies this, while buggy fails when divisible by 15.
        if (blk % 15 == 0) {
            assertTrue(balAfter > balBefore);
        } else {
            assertTrue(balAfter < balBefore);
        }
    }
}

